# Let me try a different approach - use a SAT solver with a more compact encoding
# First, let me check what's available

import importlib
for mod_name in ['pysat', 'z3', 'pycosat', 'python_sat']:
    try:
        importlib.import_module(mod_name)
        print(f"{mod_name} is available")
    except ImportError:
        print(f"{mod_name} not available")

import z3

# Let me try different placements of 0 and 46
# The vertices are indexed as (g,i) where g in 0..4, i in 0..3
# Adjacent pairs:
# - Within same clique: (g,i) and (g,j) for i<j
# - Between consecutive cliques: (g,i) and (g+1,i)

# Let me try all possible adjacent pairs for {0,46}
# and see if any leads to a solution

def try_placement(zero_pos, fortysix_pos):
    V = [[z3.BitVec(f'v_{g}_{i}', 6) for i in range(4)] for g in range(5)]
    solver = z3.Solver()

    for g in range(5):
        for i in range(4):
            solver.add(z3.And(V[g][i] >= 0, V[g][i] <= 46))

    all_vars = [V[g][i] for g in range(5) for i in range(4)]
    solver.add(z3.Distinct(all_vars))

    # Fix 0 and 46
    solver.add(V[zero_pos[0]][zero_pos[1]] == 0)
    solver.add(V[fortysix_pos[0]][fortysix_pos[1]] == 46)

    # Build adjacency
    adj = {}
    for g in range(5):
        for i in range(4):
            adj[(g,i)] = []

    for g in range(5):
        for i in range(4):
            for j in range(i+1, 4):
                adj[(g,i)].append((g,j))
                adj[(g,j)].append((g,i))

    for g in range(4):
        for i in range(4):
            adj[(g,i)].append((g+1,i))
            adj[(g+1,i)].append((g,i))

    edge_diffs = []
    for g in range(5):
        for i in range(4):
            for nb in adj[(g,i)]:
                if (g,i) < nb:
                    u = V[g][i]
                    v = V[nb[0]][nb[1]]
                    diff = z3.If(u >= v, u - v, v - u)
                    edge_diffs.append(diff)

    solver.add(z3.Distinct(edge_diffs))
    for d in edge_diffs:
        solver.add(d >= 1)
        solver.add(d <= 46)

    result = solver.check()
    if result == z3.sat:
        model = solver.model()
        labels = []
        for g in range(5):
            for i in range(4):
                labels.append(model[V[g][i]].as_long())
        return True, labels
    return False, None

# Generate all adjacent pairs
adjacent_pairs = []
# Within cliques
for g in range(5):
    for i in range(4):
        for j in range(i+1, 4):
            adjacent_pairs.append(((g,i), (g,j)))
# Between consecutive cliques
for g in range(4):
    for i in range(4):
        adjacent_pairs.append(((g,i), (g+1,i)))

print(f"Total adjacent pairs to try: {len(adjacent_pairs)}")

for zero_pos, fortysix_pos in adjacent_pairs:
    found, labels = try_placement(zero_pos, fortysix_pos)
    if found:
        print(f"Found! zero at {zero_pos}, 46 at {fortysix_pos}")
        print(labels)
        break
    else:
        print(f"No: zero at {zero_pos}, 46 at {fortysix_pos}")
